scwin.init_rowCopy = async function () {
    const rows = [{ childId: "__rb2", fn: function () { return String(dlt_irDataIrDataAttachVO.getCellData(0, "attachFileNm")); } },
        { childId: "__rb3", fn: function () { return String(dlt_irDataIrDataAttachVO.getCellData(1, "attachFileNm")); } },
        { childId: "btn_Register", fn: function () { return String(((String(((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : "")(dma_pageContext.get("statTpCd"))) === "1") ? "임시저장" : "수정")); } }];
    let copied = 0;
    for (let i = 0; i < rows.length; i++) {
        const it = rows[i];
        const c = $c.util.getComponent(it.childId);
        if (!c || typeof c.setValue !== "function") { console.warn("[sdd] 행 복사 대상 부재: " + it.childId); continue; }
        try {
            const v = it.fn();
            if (v !== undefined && v !== null && String(v).trim() !== "") { c.setValue(String(v)); copied++; }
        } catch (e) { await $c.exception.handleError(e, { notify: "none", context: "rowCopy:" + it.childId }); }
    }
    return copied;
};

