/**
 * @method
 * @name scwin.deleteAttachFile
 * @author Inswave
 * @date 2026. 09. 29
 * @param resoroomId attachSeq i
 * @returns
 * @hidden N
*/
scwin.deleteAttachFile = function (resoroomId, attachSeq, i) {
    /* sdd-asis-lifecycle:begin fn_deleteAttachFile — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const frm = (document.irDataForm || { elements: [] });
    $c.util.getComponent('dma_SearchReq').set('resoroomId', resoroomId);
    let pafObj = "";
    let fileUpObj = "";
    if (i === "1") {
        pafObj = $c.util.getComponent("presentAttachFile1");
        fileUpObj = $c.util.getComponent("fileUpBtn1");
    } else {
        pafObj = $c.util.getComponent("presentAttachFile2");
        fileUpObj = $c.util.getComponent("fileUpBtn2");
    }
    pafObj.innerText = "현재 등록된 파일 : 없음.";
    fileUpObj.innerHTML = "<span id='attachFile[" + (i - 1) + "]'><input type='file' name='attachFile[" + (i - 1) + "]' id='attachFile" + (i - 1) + "' title='파일" + i + "' style='width:500;' onblur='chkFile(this);'/></span>";
    fileUpObj.innerHTML += "<input type='hidden' id='attachFile" + (i - 1) + "Size' name='attachFile" + (i - 1) + "Size' value='0' />";
    scwin.realCnt++;
    if (scwin.realCnt <= 1) {
        scwin.delChk += attachSeq;
    } else {
        scwin.delChk += ',' + attachSeq;
    }
    $c.util.getComponent('dma_SearchReq').set('delChk', scwin.delChk);
    /* sdd-asis-lifecycle:end */
};


async function chkFile(obj) {
    /* sdd-asis-lifecycle:begin fn_chkFile — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    if (obj.value === '') {
        return false;
    }
    const notFileType = new Array("js", "css", "html", "htm", "xml", "jsp", "asp", "php");
    const fileFullNm = obj.value;
    const fileNm = fileFullNm.substring(fileFullNm.lastIndexOf("\\") + 1);
    const fileType = fileFullNm.substring(fileFullNm.lastIndexOf(".") + 1).toLowerCase();
    for (i = 0; i < notFileType.length; i++) {
        if (notFileType[i] === fileType) {
            await $c.win.alert("선택하신 파일(" + fileNm + ")에서 " + notFileType[i] + " 파일 확장자는 사용하실 수 없습니다.");
            ($c.util.getComponent(obj.parentNode.id) && $c.util.getComponent(obj.parentNode.id).setValue) ? $c.util.getComponent(obj.parentNode.id).setValue("<input type='file' id='" + obj.id + "' name='" + obj.name + "' size='60' class='form_search' onblur='chkFile(this);'  alt='첨부파일명' maxlength='80'/>") : (($c.util.getComponent(obj.parentNode.id) && $c.util.getComponent(obj.parentNode.id).setText) ? $c.util.getComponent(obj.parentNode.id).setText("<input type='file' id='" + obj.id + "' name='" + obj.name + "' size='60' class='form_search' onblur='chkFile(this);'  alt='첨부파일명' maxlength='80'/>") : (console.warn('[sdd] 값 쓰기 미지원 컴포넌트: ' + obj.parentNode.id), void ("<input type='file' id='" + obj.id + "' name='" + obj.name + "' size='60' class='form_search' onblur='chkFile(this);'  alt='첨부파일명' maxlength='80'/>")));
            return false;
        }
    }
    const fileSize = 1024;
    if (fileSize / 1024 > 10240) {
        await $c.win.alert("선택하신 " + fileNm + " 파일의 최대 크기는 30M를 넘을 수 없습니다.");
        ($c.util.getComponent(obj.parentNode.id) && $c.util.getComponent(obj.parentNode.id).setValue) ? $c.util.getComponent(obj.parentNode.id).setValue("<input type='file'  id='" + obj.id + "' name='" + obj.name + "' size='60' class='form_search' onblur='chkFile(this);'  alt='첨부파일명' maxlength='80'/>") : (($c.util.getComponent(obj.parentNode.id) && $c.util.getComponent(obj.parentNode.id).setText) ? $c.util.getComponent(obj.parentNode.id).setText("<input type='file'  id='" + obj.id + "' name='" + obj.name + "' size='60' class='form_search' onblur='chkFile(this);'  alt='첨부파일명' maxlength='80'/>") : (console.warn('[sdd] 값 쓰기 미지원 컴포넌트: ' + obj.parentNode.id), void ("<input type='file'  id='" + obj.id + "' name='" + obj.name + "' size='60' class='form_search' onblur='chkFile(this);'  alt='첨부파일명' maxlength='80'/>")));
        return false;
    }
    $c.util.getComponent(obj.id + "Size").setValue(fileSize);
    fn_IsExceedMaxLen(obj);
    /* sdd-asis-lifecycle:end */
}

